import { SupabaseClient } from '@supabase/supabase-js';
import { differenceInDays, startOfDay, parseISO, isSameDay, subDays, format } from 'date-fns';

export interface UserProfile {
  id: string;
  start_date: string;
  current_day: number;
  status: 'active' | 'failed' | 'completed';
}

export interface DailyLog {
  id?: string;
  user_id: string;
  date: string;
  tasks: boolean[]; // Array of 6 bools
  sleep_hours: number;
  completed: boolean;
}

// Ensure 6 tasks are complete and sleep >= 6 hours
export function validateDailyState(tasks: boolean[], sleep_hours: number): boolean {
  const allTasksCompleted = tasks.length === 6 && tasks.every((t) => t === true);
  return allTasksCompleted && sleep_hours >= 6;
}

export async function evaluateLazyReset(
  supabase: SupabaseClient,
  userId: string,
  userCurrentDateParam: Date // User's local time interpreted as Date
): Promise<{ failed: boolean; reason?: string }> {
  // 1. Get User Profile
  const { data: user, error: userErr } = await supabase
    .from('users')
    .select('*')
    .eq('id', userId)
    .single();

  if (userErr || !user) return { failed: false };
  if (user.status !== 'active') return { failed: false }; // Already failed or completed
  
  const localToday = startOfDay(userCurrentDateParam);
  const startDate = parseISO(user.start_date);
  
  // Calculate expected day (e.g. Day 1 is diff 0)
  const expectedDay = differenceInDays(localToday, startDate) + 1;
  const yesterday = subDays(localToday, 1);

  // If start_date is in the future, don't fail them yet
  if (expectedDay <= 0) return { failed: false };

  // If expectedDay is 1, they haven't had a chance to miss yesterday
  if (expectedDay === 1) return { failed: false };

  // Fetch yesterday's log to see if they completed it
  const { data: yesterdayLog } = await supabase
    .from('daily_logs')
    .select('*')
    .eq('user_id', userId)
    .eq('date', format(yesterday, 'yyyy-MM-dd'))
    .single();

  if (!yesterdayLog || !yesterdayLog.completed) {
    // Missing log entirely or it was marked incomplete
    const reason = !yesterdayLog 
      ? 'Did not log anything for yesterday.' 
      : 'Did not complete yesterday’s requirements by end of day.';
      
    await processFailure(supabase, userId, localToday, reason);
    return { failed: true, reason };
  }

  // Need to verify all days prior? In our strict system, missing a day resets start_date.
  // So if previous day is complete, we assume prior days were complete, unless they skipped a day entirely.
  // Let's do a quick count of total completed days
  const { count } = await supabase
    .from('daily_logs')
    .select('*', { count: 'exact', head: true })
    .eq('user_id', userId)
    .eq('completed', true)
    .gte('date', user.start_date);

  // Total completed days strictly equals expectedDay - 1
  if (count !== null && count < expectedDay - 1) {
    const reason = 'Missed logging one or more days in your challenge sequence.';
    await processFailure(supabase, userId, localToday, reason);
    return { failed: true, reason };
  }

  // If completed 75 days!
  if (count === 75 && user.status !== 'completed') {
    await supabase.from('users').update({ status: 'completed' }).eq('id', userId);
  }

  return { failed: false };
}

async function processFailure(supabase: SupabaseClient, userId: string, localToday: Date, reason: string) {
  // 1. Log failure
  await supabase.from('failures').insert({
    user_id: userId,
    date: format(localToday, 'yyyy-MM-dd'),
    reason
  });

  // 2. Reset user profile
  await supabase.from('users').update({
    start_date: format(localToday, 'yyyy-MM-dd'),
    current_day: 1,
    status: 'failed'
  }).eq('id', userId);
}
