"use client";

import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";
import { evaluateLazyReset, validateDailyState, type UserProfile, type DailyLog } from "@/lib/hardRules";
import TaskChecklist from "@/components/TaskChecklist";
import FailureScreen from "@/components/FailureScreen";
import { differenceInDays, startOfDay, format } from "date-fns";
import { Dumbbell, LogOut, CheckCircle, Calendar } from "lucide-react";
import StatsDashboard from "@/components/StatsDashboard";

export default function Dashboard() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [dailyLog, setDailyLog] = useState<DailyLog | null>(null);
  const [tasks, setTasks] = useState<boolean[]>([false, false, false, false, false, false]);
  const [sleepHours, setSleepHours] = useState<number>(0);
  const [dayCompleted, setDayCompleted] = useState<boolean>(false);
  const [showStats, setShowStats] = useState(false);

  // Failure flow
  const [failedReason, setFailedReason] = useState<string | null>(null);

  const loadData = useCallback(async (userId: string, userEmail: string, userMetadata: any) => {
    // Note: evaluateLazyReset uses the client's current date/time to determine startOfDay checks
    const today = new Date();
    
    // 1. Evaluate lazy reset first
    const failStatus = await evaluateLazyReset(supabase, userId, today);
    if (failStatus.failed) {
      setFailedReason(failStatus.reason || "You failed to complete all requirements.");
      setLoading(false);
      return;
    }

    // 2. Load User Profile
    const { data: profile } = await supabase.from("users").select("*").eq("id", userId).single();
    if (!profile) {
      // Create user if not exists using actual session email and metadata
      const { data: newProfile } = await supabase.from("users").insert({ 
        id: userId, 
        email: userEmail,
        first_name: userMetadata?.first_name || 'Guest',
        last_name: userMetadata?.last_name || 'User',
        username: userMetadata?.username || `user_${userId.slice(0, 6)}`
      }).select().single();
      setUserProfile(newProfile);
    } else {
      setUserProfile(profile);
    }

    // 3. Load or Create Today's Log safely mapped to local timezone date
    const todayStr = format(today, 'yyyy-MM-dd');
    let { data: log } = await supabase.from("daily_logs").select("*").eq("user_id", userId).eq("date", todayStr).single();

    if (!log) {
      // insert blanks
      const { data: newLog } = await supabase.from("daily_logs").insert({
        user_id: userId,
        date: todayStr,
      }).select().single();
      log = newLog;
    }

    setDailyLog(log);
    setTasks(log?.tasks || [false, false, false, false, false, false]);
    setSleepHours(log?.sleep_hours || 0);
    setDayCompleted(log?.completed || false);
    setLoading(false);
  }, []);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (!session) {
        router.push("/login");
      } else {
        loadData(session.user.id, session.user.email || 'unknown@example.com', session.user.user_metadata || {});
      }
    });
  }, [router, loadData]);

  const saveLog = async (newTasks: boolean[], newSleep: number, completedStatus: boolean) => {
    if (!dailyLog) return;
    const { data: session } = await supabase.auth.getSession();
    if (!session?.session) return;

    await supabase.from("daily_logs").update({
      tasks: newTasks,
      sleep_hours: newSleep,
      completed: completedStatus,
      updated_at: new Date().toISOString()
    }).eq("id", dailyLog.id);
  };

  const handleTaskToggle = (index: number) => {
    if (dayCompleted) return;
    setTasks(prevTasks => {
      const newTasks = [...prevTasks];
      newTasks[index] = !newTasks[index];
      
      // Save log synchronously with the explicit new array
      saveLog(newTasks, sleepHours, false);
      return newTasks;
    });
  };

  const handleSleepChange = (hours: number) => {
    if (dayCompleted) return;
    setSleepHours(hours);
    
    setTasks(prevTasks => {
      const newTasks = [...prevTasks];
      newTasks[5] = hours >= 6; // Automatically mark task 6 as complete if sleep >= 6
      saveLog(newTasks, hours, false);
      return newTasks;
    });
  };

  const submitDay = async () => {
    const isValid = validateDailyState(tasks, sleepHours);
    if (!isValid) return;

    if (!confirm("Are you sure you want to mark today as fully complete? You cannot undo this action.")) {
      return;
    }

    setDayCompleted(true);
    await saveLog(tasks, sleepHours, true);
  };

  const acknowledgeFailure = () => {
    setFailedReason(null);
    setLoading(true);
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        loadData(session.user.id, session.user.email || 'unknown@example.com', session.user.user_metadata || {});
      }
    });
  };

  const logout = async () => {
    await supabase.auth.signOut();
    router.push("/login");
  };

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background">
        <Dumbbell className="animate-spin text-primary w-10 h-10" />
      </div>
    );
  }

  // Calculate day based on difference between today and start_date
  let currentDayNum = 1;
  if (userProfile?.start_date) {
    const todayStr = startOfDay(new Date());
    currentDayNum = differenceInDays(todayStr, new Date(userProfile.start_date)) + 1;
  }

  // Calculate total tasks done (0 - 6)
  const completedCount = tasks.filter(Boolean).length;
  const progressPercent = (completedCount / 6) * 100;
  const isSubmitEnabled = completedCount === 6 && sleepHours >= 6;

  return (
    <div className="min-h-screen bg-background text-foreground pb-24">
      {/* Header */}
      <header className="p-6 flex items-center justify-between border-b border-border/50 bg-dark-panel/50 backdrop-blur-md sticky top-0 z-30">
        <div>
          <h1 className="text-xl font-black uppercase tracking-widest text-primary">75 Hard</h1>
          <p className="text-xs text-gray-500 font-semibold tracking-wider h-4">{dayCompleted ? "REST UP." : "GET IT DONE."}</p>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setShowStats(true)} className="p-2 bg-border/50 text-gray-400 rounded-full hover:bg-border hover:text-white transition shadow-sm">
            <Calendar className="w-5 h-5" />
          </button>
          <button onClick={logout} className="p-2 bg-border/50 text-gray-400 rounded-full hover:bg-border transition shadow-sm">
            <LogOut className="w-5 h-5" />
          </button>
        </div>
      </header>

      {failedReason && (
        <FailureScreen reason={failedReason} onAcknowledge={acknowledgeFailure} />
      )}

      {/* Main Content */}
      <main className="p-6 flex flex-col items-center">
        {/* Progress Display */}
        <div className="relative mb-10 mt-4">
          <div className="w-48 h-48 rounded-full border-[10px] border-border flex flex-col items-center justify-center bg-dark-panel shadow-2xl relative">
            <svg className="absolute inset-0 w-full h-full -rotate-90 transform" viewBox="0 0 100 100">
              <circle
                cx="50"
                cy="50"
                r="45"
                fill="none"
                stroke="currentColor"
                strokeWidth="10"
                className="text-primary transition-all duration-1000 ease-out"
                strokeDasharray={`${progressPercent * 2.83} 283`}
              />
            </svg>
            <span className="text-gray-400 font-semibold uppercase tracking-widest text-xs mb-1 z-10 block">Day</span>
            <span className="text-5xl font-black text-white tracking-tighter z-10 leading-none">{currentDayNum}</span>
            <span className="text-primary font-bold text-sm mt-1 z-10">/ 75</span>
          </div>
        </div>

        <TaskChecklist
          tasks={tasks}
          sleepHours={sleepHours}
          onTaskToggle={handleTaskToggle}
          onSleepChange={handleSleepChange}
          dayCompleted={dayCompleted}
        />

        {/* Submit Button */}
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-background via-background/90 to-transparent z-20">
          {dayCompleted ? (
            <div className="w-full max-w-md mx-auto py-4 rounded-full bg-success/10 text-success border border-success/30 font-bold uppercase tracking-widest flex items-center justify-center gap-2">
              <CheckCircle className="w-6 h-6" />
              Day Complete
            </div>
          ) : (
            <button
              onClick={submitDay}
              disabled={!isSubmitEnabled}
              className={`w-full max-w-md mx-auto py-5 rounded-full font-black uppercase tracking-widest transition-all duration-300 transform active:scale-95 shadow-xl block ${
                isSubmitEnabled 
                  ? "bg-primary text-white hover:bg-primary-hover hover:shadow-primary/20 hover:-translate-y-1" 
                  : "bg-dark-panel text-gray-500 border border-border cursor-not-allowed"
              }`}
            >
              Mark Day Complete
            </button>
          )}
        </div>
      </main>

      {/* Stats Dashboard Overlay */}
      {showStats && userProfile && (
        <StatsDashboard 
          userId={userProfile.id}
          startDate={userProfile.start_date}
          currentDayNum={currentDayNum}
          onClose={() => setShowStats(false)}
        />
      )}
    </div>
  );
}
