"use client";

import { CheckCircle2, Circle } from "lucide-react";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

const TASK_LABELS = [
  "Workout 1 (45 mins)",
  "Workout 2 (45 mins, Outdoors)",
  "Follow Diet",
  "Drink 1 Gallon of Water",
  "Read 10 Pages (Non-Fiction)",
  "Progress Picture", // Wait. The prompt says "Read 10 pages, Sleep at least 6 hours, etc. Wait, let me double check the prompt requirements: "1. Workout 1, 2. Workout 2 (outdoors), 3. Diet, 4. 1 Gallon Water, 5. Read 10 pages, 6. Sleep at least 6 hours".
];

const PROMPT_TASK_LABELS = [
  "Workout 1 (45 mins)",
  "Workout 2 (45 mins, Outdoors)",
  "Follow your Diet",
  "Drink 1 Gallon of Water",
  "Read 10 Pages (Non-fiction)",
  "Sleep at least 6 hours", // Actually, the prompt says "Sleep at least 6 hours" is one of the 6. Wait! "Users must complete ALL 6 daily tasks: 1. Workout 1, 2. Workout 2, 3. Follow diet, 4. Drink 1 gallon, 5. Read 10 pages, 6. Sleep at least 6 hours". 
  // Wait, the prompt says "Show 6 daily tasks as large tappable checklist items... Sleep tracking: User inputs number of hours slept (numeric input)". So we basically have 5 boolean tasks and 1 numeric task that must be >= 6. We can represent tasks as an array of 6 items in DB, where the 6th is just tracked as true if sleep >= 6.
];

interface TaskChecklistProps {
  tasks: boolean[];
  sleepHours: number;
  onTaskToggle: (index: number) => void;
  onSleepChange: (hours: number) => void;
  dayCompleted: boolean;
}

export default function TaskChecklist({ tasks, sleepHours, onTaskToggle, onSleepChange, dayCompleted }: TaskChecklistProps) {
  return (
    <div className="space-y-4 w-full max-w-md mx-auto">
      {PROMPT_TASK_LABELS.map((label, index) => {
        if (index === 5) {
          // Special render for sleep
          const isSleepSufficient = sleepHours >= 6;
          return (
            <div key={index} className="flex flex-col gap-3 p-4 rounded-xl bg-dark-panel border border-border">
              <div className="flex items-center justify-between">
                <span className={cn("text-lg font-medium", isSleepSufficient ? "text-gray-400 line-through" : "text-foreground")}>
                  {label}
                </span>
                {isSleepSufficient ? (
                  <CheckCircle2 className="w-6 h-6 text-success" />
                ) : (
                  <Circle className="w-6 h-6 text-gray-500" />
                )}
              </div>
              <div className="flex items-center gap-4">
                <input
                  type="range"
                  min="0"
                  max="12"
                  step="0.5"
                  value={sleepHours}
                  disabled={dayCompleted}
                  onChange={(e) => onSleepChange(parseFloat(e.target.value))}
                  className="w-full accent-primary"
                />
                <span className="text-xl font-bold w-12 text-right">{sleepHours}h</span>
              </div>
            </div>
          );
        }

        // Normal boolean tasks
        const isComplete = tasks[index];
        return (
          <button
            key={index}
            onClick={() => onTaskToggle(index)}
            disabled={dayCompleted}
            className={cn(
              "w-full flex items-center justify-between p-5 rounded-xl border transition-all active:scale-95 disabled:opacity-50 disabled:pointer-events-none",
              isComplete 
                ? "bg-success/10 border-success/30 text-gray-400" 
                : "bg-dark-panel border-border text-foreground hover:border-primary/50"
            )}
          >
            <span className={cn("text-lg font-medium text-left", isComplete && "line-through")}>
              {label}
            </span>
            {isComplete ? (
              <CheckCircle2 className="w-7 h-7 text-success flex-shrink-0" />
            ) : (
              <Circle className="w-7 h-7 text-gray-500 flex-shrink-0" />
            )}
          </button>
        );
      })}
    </div>
  );
}
