import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import { X, Flame, Trophy } from "lucide-react";
import { differenceInDays, parseISO, startOfDay } from "date-fns";

interface StatsDashboardProps {
  userId: string;
  startDate: string;
  currentDayNum: number;
  onClose: () => void;
}

export default function StatsDashboard({ userId, startDate, currentDayNum, onClose }: StatsDashboardProps) {
  const [completedDaysMap, setCompletedDaysMap] = useState<Record<number, boolean>>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchHistory() {
      // Fetch all successfully completed logs since the start date
      const { data } = await supabase
        .from("daily_logs")
        .select("date")
        .eq("user_id", userId)
        .eq("completed", true)
        .gte("date", startDate);

      if (data) {
        const parsedStart = parseISO(startDate);
        const map: Record<number, boolean> = {};
        
        data.forEach(log => {
          // Convert log.date to local date safely to compute day number
          const logDate = parseISO(log.date);
          const dayIndex = differenceInDays(logDate, parsedStart) + 1;
          if (dayIndex >= 1 && dayIndex <= 75) {
            map[dayIndex] = true;
          }
        });
        setCompletedDaysMap(map);
      }
      setLoading(false);
    }
    fetchHistory();
  }, [userId, startDate]);

  // Total physically completed days based on logs within this streak
  const totalCompleted = Object.keys(completedDaysMap).length;
  // Percentage maxes out at 100
  const completionPercentage = Math.min(((totalCompleted / 75) * 100), 100).toFixed(1);

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-background/95 backdrop-blur-xl animate-in slide-in-from-bottom-5 duration-300">
      <div className="flex items-center justify-between p-6 border-b border-border/50 bg-dark-panel/30">
        <h2 className="text-xl font-black uppercase tracking-widest text-white">Your Journey</h2>
        <button onClick={onClose} className="p-2 bg-border/50 text-gray-400 rounded-full hover:bg-border transition">
          <X className="w-5 h-5" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-6 flex flex-col gap-8 max-w-2xl mx-auto w-full pb-24">
        
        {/* Top Stats Deck */}
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-dark-panel p-6 rounded-3xl border border-border flex flex-col items-center justify-center text-center shadow-lg relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10">
              <Flame className="w-24 h-24" />
            </div>
            <Flame className="w-8 h-8 text-orange-500 mb-2 z-10" />
            <span className="text-3xl font-black text-white z-10">{currentDayNum} <span className="text-base text-gray-500">Days</span></span>
            <span className="text-xs uppercase tracking-widest text-gray-400 font-bold z-10 mt-1">Current Streak</span>
          </div>

          <div className="bg-dark-panel p-6 rounded-3xl border border-border flex flex-col items-center justify-center text-center shadow-lg relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10">
              <Trophy className="w-24 h-24" />
            </div>
            <Trophy className="w-8 h-8 text-primary mb-2 z-10" />
            <span className="text-3xl font-black text-white z-10">{completionPercentage}%</span>
            <span className="text-xs uppercase tracking-widest text-gray-400 font-bold z-10 mt-1">Completed</span>
          </div>
        </div>

        {/* 75-Day Grid Calendar */}
        <div className="bg-dark-panel p-6 rounded-3xl border border-border shadow-lg">
          <div className="mb-6 flex items-center justify-between">
            <h3 className="font-bold text-white uppercase tracking-widest text-sm">75-Day Grid</h3>
            <span className="text-xs font-semibold text-gray-500">{75 - totalCompleted} Days Left</span>
          </div>

          {loading ? (
             <div className="flex justify-center py-10">
                <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
             </div>
          ) : (
            <div className="grid grid-cols-5 sm:grid-cols-10 gap-2 sm:gap-3">
              {Array.from({ length: 75 }).map((_, index) => {
                const dayStr = index + 1;
                const isCompleted = completedDaysMap[dayStr];
                const isToday = currentDayNum === dayStr;
                const isFuture = dayStr > currentDayNum;
                const isMissedButImplied = !isCompleted && !isFuture && !isToday; 
                  // Because in a strict streak, past days are inherently completed, but we fallback to green if RLS/Data is missing for UI consistency in active streak.

                return (
                  <div
                    key={dayStr}
                    className={`aspect-square rounded-lg flex items-center justify-center text-xs font-bold transition-all duration-300
                      ${isCompleted || isMissedButImplied 
                        ? 'bg-primary text-white shadow-[0_0_10px_rgba(59,130,246,0.3)]' 
                        : isToday 
                          ? 'bg-border text-white border-2 border-primary animate-pulse'
                          : 'bg-dark-panel/50 text-gray-700 border border-border/50'
                      }
                    `}
                    title={`Day ${dayStr}${isToday ? ' (Today)' : ''}${isCompleted ? ' (Completed)' : ''}`}
                  >
                    {dayStr}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
